def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    unprov_d = 0
    prev = None
    for me, op in history:
        if op == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1
        if prev is None:
            if op == 'D':
                unprov_d += 1
        elif prev == 'C' and op == 'D':
            unprov_d += 1
        prev = me

    opp_c = n - opp_d
    if opp_c == 0:
        return 'D'

    mutual_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_streak += 1
        else:
            break

    recent_len = min(8, n)
    recent_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_d += 1
    recent_c = recent_len - recent_d

    if last_opp == 'C':
        if n >= 8:
            c_after_c = 0
            d_after_c = 0
            c_after_d = 0
            d_after_d = 0
            for i in range(1, n):
                pm = history[i - 1][0]
                op = history[i][1]
                if pm == 'C':
                    if op == 'C':
                        c_after_c += 1
                    else:
                        d_after_c += 1
                else:
                    if op == 'C':
                        c_after_d += 1
                    else:
                        d_after_d += 1

            tot_c = c_after_c + d_after_c
            tot_d = c_after_d + d_after_d
            if tot_c >= 3 and tot_d >= 2:
                p_c = float(c_after_c) / float(tot_c)
                p_d = float(c_after_d) / float(tot_d)
                if (1.0 + 4.0 * p_d) > (3.0 * p_c + 1.1):
                    return 'D'

        if opp_d == 0 and my_d > 0:
            return 'D'

        if last_me == 'D' and recent_c == recent_len and opp_c * 10 > n * 9:
            if rng.random() < 0.4:
                return 'D'

        return 'C'

    if recent_c == 0 and opp_d * 5 > n * 3:
        return 'D'

    if opp_d * 5 > n * 3 and recent_d >= recent_len - 1:
        return 'D'

    if opp_d * 5 > n * 3 and unprov_d * 2 > n:
        return 'D'

    if last_me == 'C':
        return 'D'

    if mutual_streak == 1:
        if opp_c * 10 > n * 6 and unprov_d <= 2:
            return 'C'
        if opp_c * 10 > n * 4 and unprov_d <= 1:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    if opp_c * 10 > n * 7 and unprov_d <= 2 and mutual_streak <= 3:
        return 'C'

    if opp_c * 10 > n * 5 and unprov_d <= 3:
        if rng.random() < 0.25:
            return 'C'

    if recent_c * 10 > recent_len * 7:
        if rng.random() < 0.2:
            return 'C'

    return 'D'
